class Solution:
    def snakesAndLadders(self, board: List[List[int]]) -> int:
        n = len(board)
        board.reverse()

        def get_pos(square):
            row = (square - 1) // n
            col = (square - 1) % n
            if row % 2 == 1:
                col = n - 1 - col
            return row, col

        q = [(1, 0)]  # (square, moves)
        visited = {1}

        while q:
            square, moves = q.pop(0)

            if square == n * n:
                return moves

            for next_square in range(square + 1, min(square + 6, n * n) + 1):
                row, col = get_pos(next_square)
                destination = board[row][col]

                if destination != -1:
                    next_pos = destination
                else:
                    next_pos = next_square

                if next_pos not in visited:
                    visited.add(next_pos)
                    q.append((next_pos, moves + 1))

        return -1

