class Solution:
    def minCameraCover(self, root: Optional[TreeNode]) -> int:
        def dfs(node):
            """
            Return a tuple (covered, camera_needed) where:
            - covered: 0 if not covered, 1 if covered, 2 if has camera
            - camera_needed: number of cameras needed in this subtree
            """
            if not node:
                return 1, 0  # Covered by parent

            left_covered, left_cameras = dfs(node.left)
            right_covered, right_cameras = dfs(node.right)

            if left_covered == 0 or right_covered == 0:
                # Need to place a camera here
                return 2, left_cameras + right_cameras + 1
            elif left_covered == 1 and right_covered == 1:
                # Both children are covered, so this node is covered
                return 1, left_cameras + right_cameras
            else:
                # One child is covered, the other has a camera
                return 1, left_cameras + right_cameras

        covered, cameras = dfs(root)
        if covered == 0:
            cameras += 1  # Need to place a camera at the root
        return cameras

