    def verticalTraversal(self, root: Optional[TreeNode]) -> List[List[int]]:
        if not root:
            return []

        column_map = {}
        queue = [(root, 0, 0)]  # (node, column, row)

        while queue:
            node, column, row = queue.pop(0)

            if column not in column_map:
                column_map[column] = []
            column_map[column].append((row, node.val))

            if node.left:
                queue.append((node.left, column - 1, row + 1))
            if node.right:
                queue.append((node.right, column + 1, row + 1))

        sorted_columns = sorted(column_map.keys())
        result = []

        for column in sorted_columns:
            column_map[column].sort()  # Sort by row, then by value
            result.append([val for row, val in column_map[column]])

