class Solution:
    def recoverFromPreorder(self, traversal: str) -> Optional[TreeNode]:
        def helper(traversal, start):
            if start >= len(traversal):
                return None, start

            val_end = start
            while val_end < len(traversal) and traversal[val_end].isdigit():
                val_end += 1

            val = int(traversal[start:val_end])
            node = TreeNode(val)

            if val_end < len(traversal) and traversal[val_end] == '-':
                node.left, next_start = helper(traversal, val_end + 1)
                if next_start < len(traversal) and traversal[next_start] == '-':
                    node.right, next_start = helper(traversal, next_start + 1)
                return node, next_start
            else:
                return node, val_end

        root, _ = helper(traversal, 0)
        return root

