    def max_possible_f(self, n: int, edges: List[List[int]], usage: List[int]) -> int:
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        visited = [False] * n
        q = []

        for i in range(n):
            if usage[i] == 1:
                q.append(i)
                visited[i] = True

        level = 0
        while q:
            next_level = []
            for u in q:
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        next_level.append(v)
            q = next_level
            level += 1

        reachable_count = sum(visited)

        return reachable_count
